package io.lerk.lrkFM.adapter;

import android.annotation.SuppressLint;
import android.content.ActivityNotFoundException;
import android.content.Context;
import android.content.Intent;
import android.net.Uri;
import android.os.Vibrator;
import android.view.LayoutInflater;
import android.view.View;
import android.widget.CheckBox;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.TextView;
import android.widget.Toast;

import java.text.SimpleDateFormat;
import java.util.List;
import java.util.Objects;

import io.lerk.lrkFM.Pref;
import io.lerk.lrkFM.R;
import io.lerk.lrkFM.entities.FMArchive;
import io.lerk.lrkFM.entities.FMFile;
import io.lerk.lrkFM.activities.file.ContextMenuUtil;

import static android.widget.Toast.LENGTH_SHORT;
import static io.lerk.lrkFM.consts.PreferenceEntity.FILENAME_LENGTH;
import static io.lerk.lrkFM.consts.PreferenceEntity.SHOW_MENU_BUTTON_INSTEAD_OF_CHECKBOX;
import static io.lerk.lrkFM.consts.PreferenceEntity.ZIPS_EXPLORABLE;

/**
 * Heavily abused ArrayAdapter that also adds menus and listeners.
 *
 * @author Lukas Fülling (lukas@k40s.net)
 */
public class FileArrayAdapter extends BaseArrayAdapter {

    public FileArrayAdapter(Context context, int resource, List<FMFile> items) {
        super(context, resource, items);
    }

    /**
     * Opens a file using the default app.
     *
     * @param f the file
     */
    @Override
    protected void openFile(FMFile f) {
        if (new Pref<Boolean>(ZIPS_EXPLORABLE).getValue() && f.isArchive() && !(f instanceof FMArchive)) {
            activity.loadPath(f.getAbsolutePath());
        } else {
            Intent i = new Intent(Intent.ACTION_VIEW);
            i.setDataAndType(Uri.fromFile(f.getFile()), FMFile.getMimeTypeFromFile(f));
            i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
            try {
                getContext().startActivity(i);
            } catch (ActivityNotFoundException e) {
                Toast.makeText(getContext(), R.string.no_app_to_handle_file, LENGTH_SHORT).show();
            }
        }
    }

    /**
     * Gets the size of a file as formatted string.
     *
     * @param f the file
     * @return the size, formatted.
     */
    private String getSizeFormatted(FMFile f) {
        String[] units = new String[]{"B", "KiB", "MiB", "GiB", "TiB", "PiB"};
        Long length = f.getFile().length();
        if (Objects.equals(length, 0L)) {
            return "0";
        }
        Double number = Math.floor(Math.log(length) / Math.log(1024));
        Double pow = Math.pow(1024, Math.floor(number));
        Double d = length / pow;
        String formattedString = d.toString().substring(0, d.toString().indexOf(".") + 2);
        return formattedString + ' ' + units[number.intValue()];
    }

    /**
     * Initializes the UI for each file.
     *
     * @param f the file
     * @return the initialized UI
     */
    @Override
    protected View initUI(FMFile f) {
        assert activity != null;

        @SuppressLint("InflateParams") View v = LayoutInflater.from(activity).inflate(R.layout.layout_file, null); // works.

        if (f != null) {
            TextView fileNameView = v.findViewById(R.id.fileTitle);
            TextView filePermissions = v.findViewById(R.id.filePermissions);
            TextView fileDate = v.findViewById(R.id.fileDate);
            TextView fileSize = v.findViewById(R.id.fileSize);
            ImageView fileImage = v.findViewById(R.id.fileIcon);

            final String fileName = f.getName();
            if (fileNameView != null) {
                int maxLength = Integer.parseInt(new Pref<String>(FILENAME_LENGTH).getValue());
                if (fileName.length() >= maxLength) {
                    @SuppressLint("SetTextI18n") String output = fileName.substring(0, maxLength - 3) + "...";
                    fileNameView.setText(output); //shorten long names
                } else {
                    fileNameView.setText(fileName);
                }
            }
            if (filePermissions != null) {
                filePermissions.setText(f.getPermissions());
            }
            if (fileDate != null) {
                fileDate.setText(SimpleDateFormat.getDateTimeInstance().format(f.getLastModified()));
            }
            if (fileSize != null) {
                if (f.isDirectory()) {
                    fileSize.setVisibility(View.GONE);
                } else {
                    fileSize.setText(getSizeFormatted(f));
                }
            }
            if (fileImage != null) {
                if (!f.isDirectory()) {
                    if (f.isArchive()) {
                        fileImage.setImageDrawable(getContext().getDrawable(R.drawable.ic_perm_media_black_24dp));
                    } else {
                        fileImage.setImageDrawable(getContext().getDrawable(R.drawable.ic_insert_drive_file_black_24dp));
                    }
                }
            }
            if (f.isDirectory() || (f.isExplorableArchive() && new Pref<Boolean>(ZIPS_EXPLORABLE).getValue())) {
                v.setOnClickListener(v1 -> activity.loadPath(f.getFile().getAbsolutePath()));
            } else {
                v.setOnClickListener(v1 -> openFile(f));
            }
            v.setOnCreateContextMenuListener((menu, view, info) -> new ContextMenuUtil(activity, this).initializeContextMenu(f, fileName, menu));


            ImageButton contextButton = v.findViewById(R.id.contextMenuButton);
            contextButton.setOnClickListener(v1 -> {
                ((Vibrator) activity.getSystemService(Context.VIBRATOR_SERVICE)).vibrate(8);
                activity.getFileListView().showContextMenuForChild(v);
            });

            CheckBox checkBox = v.findViewById(R.id.fileCheckBox);
            checkBox.setOnCheckedChangeListener((buttonView, isChecked) -> {
                if (isChecked && !isInContext(f)) {
                    activity.getFileOpContext().getSecond().add(f);
                } else if (!isChecked && isInContext(f)) {
                    removeFromContext(f);
                }
            });

            if (new Pref<Boolean>(SHOW_MENU_BUTTON_INSTEAD_OF_CHECKBOX).getValue()) {
                checkBox.setVisibility(View.INVISIBLE);
                contextButton.setVisibility(View.VISIBLE);
            } else {
                checkBox.setVisibility(View.VISIBLE);
                contextButton.setVisibility(View.GONE);
            }

            for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
                if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
                    v.setBackgroundColor(activity.getColorByAttr(R.attr.colorPrimary));
                    checkBox.setChecked(true);
                } else {
                    checkBox.setChecked(false);
                }
            }
        }
        return v;
    }

    private boolean isInContext(FMFile f) {
        boolean res = false;
        for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
            if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
                res = true;
            }
        }
        return res;
    }

    private void removeFromContext(FMFile f) {
        for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
            if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
                activity.getFileOpContext().getSecond().remove(contextFile);
            }
        }
    }
}

steps.reasoning_content:
Now I can clearly see the bug. The issue is in the `removeFromContext` method at line 188. When the user quickly deselects multiple checkboxes, the `initUI` method is called for each view, and the `SetOnCheckedChangeListener` callback triggers `removeFromContext`. The problem is:

1. In `removeFromContext`, there's a for-each loop iterating over `activity.getFileOpContext().getSecond()` (which is an ArrayList)
2. Inside the loop, it calls `.remove(contextFile)` on the same ArrayList
3. This causes a `ConcurrentModificationException` because you can't modify a collection while iterating over it with an iterator

Similarly, the `isInContext` method at lines 175-181 has the same issue - it iterates but doesn't modify, so that's fine. But wait, in `initUI` at lines 162-170, there's:


```java
for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
    if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
        v.setBackgroundColor(activity.getColorByAttr(R.attr.colorPrimary));
        checkBox.setChecked(true);
    } else {
        checkBox.setChecked(false);
    }
}
```

When `checkBox.setChecked(true)` is called, it triggers the `SetOnCheckedChangeListener` again, which adds to the context. And when `setChecked(false)` is called, it triggers the listener to remove from context. This creates a cascading effect where modifying the checkbox state within the loop causes the listener to fire and modify the collection being iterated over.

The stack trace confirms the crash is happening in `removeFromContext` during iteration, where the `ConcurrentModificationException` occurs when trying to remove an item while looping through the collection.

The root cause is that when `checkBox.setChecked()` is called on one item, it triggers the listener which modifies the context collection for other items in the list, and then when the iterator continues through that same collection, it throws the exception.

There are two problematic loops here. The `removeFromContext` method iterates with a for-each loop and calls `remove()` on the underlying collection, which violates the iterator contract. Similarly, the loop at lines 162-170 that calls `checkBox.setChecked()` on each context file causes the listener to fire and modify the collection being iterated over.

The fix is to use an explicit Iterator and call `iterator.remove()` instead of collection.remove(), which safely handles removal during iteration. Since `activity.getFileOpContext().getSecond()` is an ArrayList, it uses a fast-fail iterator that throws ConcurrentModificationException when the collection is structurally modified outside the iterator's own remove method.

However, there's a deeper issue here—modifying the context inside `getView` itself creates a problematic feedback loop where checking a checkbox triggers state changes that affect the list being iterated. The cleaner approach would be to decouple the UI update from the state modification, but the most direct fix for the concurrent modification issue is using the iterator properly in both methods. So the bug report says:
1. Click on checkboxes
2. Deselect some checkboxes
3. Crash

When deselecting, `isChecked` is false. If `isInContext(f)` returns true, it calls `removeFromContext(f)`. In `removeFromContext`, it iterates and tries to remove. That's the crash.

But wait, there's another issue. In `initUI` at lines 162-170:
```java
for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
    if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
        ...
        checkBox.setChecked(true);
    } else {
        checkBox.setChecked(false);
    }
}
```

If `contextFile` is the same as `f`, it calls `setChecked(true)`. This triggers the listener which checks `isChecked && !isInContext(f)` - but `isChecked` is true and `isInContext(f)` would be true (since we're in the context), so it wouldn't add. But wait, the listener's first condition is `if (isChecked && !isInContext(f))`, so when isChecked is true and f is already in context, the condition is false and it doesn't add again. Good. But then for items not matching, it calls `setChecked(false)`, which triggers the else branch and removes the item from context. I need to reconsider the flow here. When the user manually checks a box, `isChecked` becomes true, but `isInContext(f)` might still return false if the context hasn't been updated yet. That means the listener would add the file to the context. Then when the ListView recycles views and `getView` is called again for the same position, it iterates through the context and calls `setChecked(true)` on what's now a recycled view holding a different file—which then triggers the listener to add that new file to the context as well.

The real issue is that setting `setChecked(true)` programmatically fires the listener, which modifies the context collection. If that collection is being iterated at that moment (like when `getView` is looping through items to update them), it causes a ConcurrentModificationException. The safest approach is to refactor `removeFromContext` to use an iterator properly, and consider using `setOnCheckedChangeListener` with a flag to prevent the listener from firing during programmatic state updates.

Refactoring the removal logic... The `isInContext` method can stay as-is since it only reads from the collection. I should also fix the problematic loop in `initUI` at lines 162-170 where `setChecked` might trigger the listener. I need to use `setOnCheckedChangeListener` with a null listener temporarily to prevent recursive callbacks, or employ a flag to suppress listener calls while updating the checkbox state programmatically. The listener needs a guard to prevent infinite loops when programmatically setting checkbox state, and `removeFromContext` should use an Iterator to safely modify the collection during iteration. These two fixes address the core issues without needing to refactor the entire architecture.

